function logWithTrace(req, level, message, extra = {}) {
  console.log(JSON.stringify({
    timestamp: new Date().toISOString(),
    level,
    traceId: req.traceId,
    message,
    ...extra
  }));
}

logWithTrace(req, 'error', 'connection pool exhausted', { service: 'payment' });

